#!/usr/bin/env bash
# AKFC — Logo du site dans les blocs : fond adapté à sa couleur (logo blanc sur blanc invisible).
#  - nouveau SiteLogoImage (client) : fond sombre pour un logo clair, clair pour un logo sombre,
#    luminance mesurée dans le navigateur (même mesure que l'aperçu des Réglages du site) ;
#    fond sombre par défaut — le cas du logo actuel : ni clignotement, ni écart serveur/client.
#  - média-texte et texte enrobant (les 3 rendus d'image) : le média « logo du site » passe par lui.
#    Vaut pour le SITE PUBLIC, l'aperçu du builder et le laboratoire (mêmes vues).
#  - laboratoire : exemple supplémentaire « texte enrobant — logo du site ».
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-site-logo-backdrop.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
C="apps/web/src/features/page-builder/components/SiteLogoImage.tsx"
[ -f "$C" ] && { echo "— déjà appliqué"; exit 0; }
[ -f apps/web/src/features/design-lab/RealBlocksPreview.tsx ] || { echo "ERREUR: applique d'abord apply-design-lab-all-blocks.sh." >&2; exit 1; }
FILES=(apps/web/src/features/page-builder/blocks/media-text/view.server.tsx apps/web/src/features/page-builder/blocks/float-text/view.server.tsx apps/web/src/features/design-lab/RealBlocksPreview.tsx)
BK=/tmp/akfc_logo_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$C"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_logo; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== application =="
echo '' | base64 -d > "$C" && echo "  ok  $C"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$C" "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(blocks): logo du site présenté sur un fond adapté à sa couleur

